// Revenue Engine - checkout conversion fix
// Ensure paidEvents increments on successful payment

const crypto = require('crypto');

let paidEvents = 0;
let conversionRate = 0;
let leads = 171150;

function recordPayment(amount, currency = 'USD') {
  paidEvents++;
  conversionRate = paidEvents / leads;
  // Log payment for audit
  console.log(`[REVENUE] Payment recorded: ${amount} ${currency} | Total paidEvents: ${paidEvents}`);
  return { success: true, paidEvents, conversionRate };
}

function getStats() {
  return { paidEvents, conversionRate, leads };
}

// Hook into checkout completion (placeholder for actual integration)
// This function should be called when a checkout is successfully completed
function onCheckoutComplete(orderId, amount) {
  return recordPayment(amount);
}

module.exports = { recordPayment, getStats, onCheckoutComplete };
